<?php
namespace App\Controllers;
use Vedairo\Http\Request;use Vedairo\Http\Response;use App\Services\CartService;
class CartController { public function __construct(private CartService $cart){} public function index():string{$data=$this->cart->items();ob_start();include base_path('resources/views/cart/index.php');return (string) ob_get_clean();} public function add(Request $r):never{try{$this->cart->add((int)$r->input('product_id'),(int)$r->input('qty',1));}catch(\Throwable $e){Response::json(['success'=>false,'message'=>$e->getMessage()],422);}Response::json(['success'=>true,'cart'=>$this->cart->items()]);} public function update(Request $r,string $id):never{$this->cart->update((int)$id,(int)$r->input('qty'));Response::json(['success'=>true,'cart'=>$this->cart->items()]);} public function remove(Request $r,string $id):never{$this->cart->remove((int)$id);Response::json(['success'=>true,'cart'=>$this->cart->items()]);} public function clear(Request $r):never{$this->cart->clear();Response::json(['success'=>true]);}}
